  host: '127.0.0.1',  // 服务器地址
  port: 6379,         // 服务器端口
  db: 0,              // 数据库号码
  prefix: 'cache:',   // key前缀
  password: 'xxx',    // 密码
  pool: 1             // 连接池数量
});
```

3、Memchache存储引擎（仅Node.js中使用）

```javascript
var store = new SuperCache.MemcacheStore({
  host: '127.0.0.1',  // 服务器地址
  port: 11211,        // 服务器端口
  prefix: 'cache:',   // key前缀
  user: 'xxx',        // 用户名
  password: 'xxx',    // 密码
  pool: 1             // 连接池数量
});
```

4、localStorage/sessionStorage存储引擎（仅浏览器中使用）

```javascript
